URL = "http://127.0.0.1:8765/ignored"


def q(files):
    """files: dict path -> content (str or bytes). Returns ignored list or error string."""
    buf = io.BytesIO()
    with tarfile.open(fileobj=buf, mode="w:gz") as tar:
        for p, c in files.items():
            if isinstance(c, str):
                c = c.encode()
            ti = tarfile.TarInfo(p)
            ti.size = len(c)
            tar.addfile(ti, io.BytesIO(c))
    req = urllib.request.Request(URL, data=buf.getvalue(), headers={"Content-Type": "application/x-tar"})
    try:
        with urllib.request.urlopen(req, timeout=60) as r:
            return json.load(r)["ignored"]
    except urllib.error.HTTPError as e:
        return "ERR: " + str(json.load(e))


def t(pi, paths, extra=None):
    files = {p: "" for p in paths}
    files[".packignore"] = pi
    if extra:
        files.update(extra)
    r = q(files)
    print(repr(pi), "->", r)
    return r

