import os, random, subprocess, sys, shutil, json
sys.path.insert(0, "/work/repo")
from snapshot.ignore import ignored_files

CLIENT = "/work/repo/tools/packignore"
NAMES = ["a", "b", "ab", "x", "y", "z", "xa", "a.b", ".h", "A", "B", "ba", "aa", "c.txt", "d"]
DIRS = ["x", "y", "z", "a", "sub", "X", "ya"]
TOK = ["a", "b", "x", "y", "z", "*", "**", "?", "/", "/", "{", "}", ",", "!", ".", "ab", "c", "txt", "[", "]", "\\", " ", "A", ";", "#", "sub", "**/", "/**"]


def gen_pattern(r):
    n = r.randint(1, 6)
    s = "".join(r.choice(TOK) for _ in range(n))
    if r.random() < 0.25:
        s = "!" + s
    return s


def gen_tree(r):
    files = {}
    dirs = [""]
    for _ in range(r.randint(1, 6)):
        parent = r.choice(dirs)
        d = (parent + "/" if parent else "") + r.choice(DIRS)
        if r.random() < 0.7 and d not in dirs:
            dirs.append(d)
    for d in dirs:
        for _ in range(r.randint(0, 4)):
            nm = r.choice(NAMES)
            p = (d + "/" if d else "") + nm
            files[p] = ""
    for d in dirs:
        if r.random() < (0.9 if d == "" else 0.4):
            lines = [gen_pattern(r) for _ in range(r.randint(1, 5))]
            files[(d + "/" if d else "") + ".packignore"] = "\n".join(lines) + "\n"
    return files


def write(root, files):
    os.makedirs(root)
    for p, c in files.items():
        full = os.path.join(root, p)
        os.makedirs(os.path.dirname(full), exist_ok=True)
        if os.path.isdir(full):
            continue
        with open(full, "w") as f:
            f.write(c)


def run(root):
    pr = subprocess.run([sys.executable, CLIENT, root], capture_output=True, text=True)
    if pr.returncode:
        exp = "ERROR " + pr.stderr.strip()
    else:
        exp = sorted(l for l in pr.stdout.splitlines() if l)
    try:
        got = ignored_files(root)
    except Exception as e:
        got = "ERROR " + repr(e)
    return exp, got


def main():
    seed0 = int(sys.argv[1]); n = int(sys.argv[2])
    base = f"/tmp/pk/fz{seed0}"
    fails = 0
    for s in range(seed0, seed0 + n):
        r = random.Random(s)
        files = gen_tree(r)
        root = f"{base}/{s}"
        try:
            write(root, files)
        except (NotADirectoryError, IsADirectoryError, FileExistsError):
            continue
        exp, got = run(root)
        if exp != got and not (isinstance(exp, str) and isinstance(got, str)):
            fails += 1
            print("SEED", s)
            for p, c in files.items():
                if p.endswith(".packignore"):
                    print("  ", p, repr(c))
            print("  files:", sorted(p for p in files if not p.endswith(".packignore")))
            e, g = set(exp) if isinstance(exp, list) else {exp}, set(got) if isinstance(got, list) else {got}
            print("  only packignore:", sorted(e - g))
            print("  only mine:", sorted(g - e))
            if fails > 5:
                break
    print("fails", fails)


main()

